"""Arithmetic expression evaluator (hand-written tokenizer + recursive descent)."""


class _Tokenizer:
    def __init__(self, text):
        self.text = text
        self.pos = 0

    def error(self, msg):
        raise ValueError(msg)

    def peek(self):
        while self.pos < len(self.text) and self.text[self.pos].isspace():
            self.pos += 1
        if self.pos >= len(self.text):
            return None
        return self.text[self.pos]

    def next_token(self):
        ch = self.peek()
        if ch is None:
            return ("EOF", None)
        if ch.isdigit() or ch == ".":
            return self._number()
        if ch.isalpha() or ch == "_":
            return self._name()
        self.pos += 1
        two = self.text[self.pos - 1: self.pos + 1]
        if two in ("**", "//"):
            self.pos += 1
            return ("OP", two)
        if ch in "+-*/%()":
            return ("OP", ch)
        if ch == ",":
            return ("COMMA", ",")
        self.error("unexpected character %r" % ch)

    def _number(self):
        start = self.pos
        self.pos += 1
        is_float = False
        if self.text[self.pos - 1] == ".":
            is_float = True
        while self.pos < len(self.text) and self.text[self.pos].isdigit():
            self.pos += 1
        if self.pos < len(self.text) and self.text[self.pos] == ".":
            if is_float:
                self.error("invalid number")
            is_float = True
            self.pos += 1
            while self.pos < len(self.text) and self.text[self.pos].isdigit():
                self.pos += 1
        literal = self.text[start:self.pos]
        value = float(literal) if is_float else int(literal)
        return ("NUM", value)

    def _name(self):
        start = self.pos
        while self.pos < len(self.text) and (self.text[self.pos].isalnum() or self.text[self.pos] == "_"):
            self.pos += 1
        return ("NAME", self.text[start:self.pos])


class _Parser:
    def __init__(self, tokens):
        self.tokens = tokens
